\set ON_ERROR_STOP on
DO $technical$ DECLARE rec record; BEGIN
SELECT p.* INTO rec FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rffusion_support' AND p.proname='allocate_id' AND p.pronargs=0;
IF NOT FOUND OR encode(sha256(convert_to(rec.prosrc,'UTF8')),'hex')<>'f5939ce0d8fd4e68a4f0da418b424f2ebcfd0f13a3cdef81b8243721d747be9c' OR rec.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(rec.proacl) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Technical function missing, changed or public: allocate_id'; END IF;
SELECT p.* INTO rec FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rffusion_support' AND p.proname='reset_generators' AND p.pronargs=0;
IF NOT FOUND OR encode(sha256(convert_to(rec.prosrc,'UTF8')),'hex')<>'70246f379dd8136202c4d90fd7f1d79e2ba77c4320870621b95ad401a6ef5639' OR rec.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(rec.proacl) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Technical function missing, changed or public: reset_generators'; END IF;
SELECT p.* INTO rec FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rffusion_support' AND p.proname='update_timestamp' AND p.pronargs=0;
IF NOT FOUND OR encode(sha256(convert_to(rec.prosrc,'UTF8')),'hex')<>'338f9bea5791bfd524cd6858638e2a814007ef4831e203269a8bcb0149df1141' OR rec.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(rec.proacl) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Technical function missing, changed or public: update_timestamp'; END IF;
SELECT p.* INTO rec FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rffusion_support' AND p.proname='normalize_role' AND p.pronargs=0;
IF NOT FOUND OR encode(sha256(convert_to(rec.prosrc,'UTF8')),'hex')<>'01985dfc7140ddb0de841fd857bb1c63d46a4b7760e1a72e9b2e0950de691683' OR rec.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(rec.proacl) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Technical function missing, changed or public: normalize_role'; END IF;
SELECT p.* INTO rec FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rffusion_support' AND p.proname='file_identity' AND p.pronargs=0;
IF NOT FOUND OR encode(sha256(convert_to(rec.prosrc,'UTF8')),'hex')<>'42efdfc02f515a5d8806dd122dbb0ad8d98df6a2f6afdca75d0ca2611bd5b201' OR rec.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(rec.proacl) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Technical function missing, changed or public: file_identity'; END IF;
IF has_schema_privilege('rffusion_appcataloga','rffusion_support','CREATE') OR has_schema_privilege('rffusion_webfusion','rffusion_support','CREATE') OR has_table_privilege('rffusion_appcataloga','rffusion_support.id_guard','SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('rffusion_webfusion','rffusion_support.identity_guard','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Application can bypass technical guards'; END IF;
END; $technical$;
